package com.orderflow.notification.service;import com.orderflow.notification.dto.NotificationResponse;import java.util.UUID;import org.springframework.scheduling.annotation.Async;import org.springframework.stereotype.Component;@Component public class AsyncNotificationFanout{private final SseRegistry registry;public AsyncNotificationFanout(SseRegistry r){registry=r;}@Async("notificationExecutor")public void publish(UUID user,NotificationResponse n){registry.send(user,n);}}
